BASE="$HOME/tcp-incident"
mkdir -p "$BASE/reports"

PORT=$(grep -E '^[[:space:]]*PORT=' "$BASE/config/api.env" 2>/dev/null | cut -d= -f2 | tr -d '[:space:]"' || echo 18202)

# Pre-seeded deterministic incident fixture representing completed Task 1 triage
cat << EOF > "$BASE/reports/queue-triage.env"
# Deterministic incident fixture generated by skip-ahead setup (not a live measurement)
SERVICE_PORT=${PORT:-18202}
CONFIGURED_BACKLOG=5
OBSERVED_SEND_Q=5
OBSERVED_RECV_Q=6
QUEUE_TYPE=ACCEPT_QUEUE
EOF

# Pre-seeded deterministic incident fixture representing completed Task 2 burst measurement
cat << 'EOF' > "$BASE/reports/metric-drops.env"
# Deterministic burst fixture generated by skip-ahead setup (not a live measurement)
BURST_CLIENT_COUNT=20
SUCCESSFUL_CONNECTS=6
FAILED_CONNECTS=14
OVERFLOW_COUNTER=ListenOverflows
DROP_COUNTER=ListenDrops
EOF

sed -i 's/^TCP_BACKLOG=.*/TCP_BACKLOG=128/' "$BASE/config/api.env"
sed -i 's/^WORKER_CONCURRENCY=.*/WORKER_CONCURRENCY=32/' "$BASE/config/api.env"
"$BASE/bin/api-ctl" restart >/dev/null 2>&1 || true

rm -f "$BASE/reports/verification.marker"
